CREATE TABLE DimDate(DateKey INTEGER PRIMARY KEY, FullDate DATE NOT NULL UNIQUE, CalendarYear INTEGER NOT NULL, CalendarQuarter INTEGER NOT NULL, CalendarMonthNumber INTEGER NOT NULL, CalendarMonthName VARCHAR NOT NULL, YearMonth VARCHAR NOT NULL, DayOfMonth INTEGER NOT NULL, DayOfWeekNumber INTEGER NOT NULL, DayOfWeekName VARCHAR NOT NULL, IsWeekend BOOLEAN NOT NULL);
